        p_body.addOrReplaceChild("wing_l",
        CubeListBuilder.create()
                .mirror(true)
                .texOffs(0, 25).addBox(0f, 0f, -2.5f, 7f, 0f, 5f)
                , PartPose.offsetAndRotation(1.25f, -3.25f, 1f, 0f, -0.3f, -0.65f));
        PartDefinition p_scarf = p_body.addOrReplaceChild("scarf",
        CubeListBuilder.create()
                .texOffs(48, 0).addBox(-3.5f, -3.5f, -0.5f, 7f, 6f, 1f)
                , PartPose.offset(0f, 0f, -2.75f));
        p_scarf.addOrReplaceChild("scarf_tail",
        CubeListBuilder.create()
                .texOffs(28, 25).addBox(-0.375f, 0f, -0.525f, 1f, 4f, 1f, new CubeDeformation(0.125f, 0f, -0.125f))
                , PartPose.offsetAndRotation(2.75f, 2f, -0.25f, 0f, 0f, -0.15f));
        return LayerDefinition.create(mesh, 64, 64);
